import ifcopenshell
import ifcopenshell.util.element

path_ifc_model = '/home/sffc348/Repos/cobbie/acc/bim_models/dental_clinic/arc.ifc'
model = ifcopenshell.open(path_ifc_model)

# Check a violating space and look at its connected doors in detail
violating_space_guid = '0ztdC3L1HAzhbhMHypqbH5'  # Central Waiting
space = model.by_guid(violating_space_guid)

print(f"Space: {space.Name} ({space.LongName})")

# Get doors via IfcRelSpaceBoundary
rel_boundaries = model.by_type('IfcRelSpaceBoundary')
for rel in rel_boundaries:
    if rel.RelatingSpace and rel.RelatingSpace.GlobalId == violating_space_guid:
        if rel.RelatedBuildingElement and 'Door' in rel.RelatedBuildingElement.is_a():
            door = rel.RelatedBuildingElement
            print(f"\nDoor: {door.Name}, GUID: {door.GlobalId}")
            print(f"  Type: {door.is_a()}")

            # Get all door properties
            door_psets = ifcopenshell.util.element.get_psets(door)
            for pset_name, props in door_psets.items():
                print(f"  {pset_name}:")
                for key, val in props.items():
                    print(f"    {key}: {val}")

# Check door types to understand what defines a 'Hatch'
print("\n=== Checking door types ===")
door_types = model.by_type('IfcDoorType')
for dt in door_types[:10]:
    print(f"\nDoorType: {dt.Name}")
    psets = ifcopenshell.util.element.get_psets(dt)
    for pset_name, props in psets.items():
        if 'Type' in props or 'Operation' in props or 'Construction' in props:
            print(f"  {pset_name}: {props}")

# Check if doors have 'OperationType' attribute
print("\n=== Checking door OperationType ===")
for rel in rel_boundaries:
    if rel.RelatingSpace and rel.RelatingSpace.GlobalId == violating_space_guid:
        if rel.RelatedBuildingElement and 'Door' in rel.RelatedBuildingElement.is_a():
            door = rel.RelatedBuildingElement
            if hasattr(door, 'OperationType'):
                print(f"Door {door.Name}: OperationType = {door.OperationType}")
